void check(bool value,const char* message){++checks;if(!value){std::fprintf(stderr,"FAIL shared PCM: %s\n",message);std::exit(1);}}
struct Backend:AudioBackend {
 uint64_t next=1;bool fail=false;std::map<uint64_t,std::shared_ptr<NativeAudioFeed>> feeds;std::map<uint64_t,bool> pauses;
 bool play(const std::vector<int16_t>&,const AudioProfile&,AudioRole,uint64_t&,std::string& e)override{e="Unexpected copied playback";return false;}
 bool playFeed(const std::shared_ptr<NativeAudioFeed>& f,const AudioProfile&,AudioRole role,uint64_t& h,std::string& e)override{check(role==kAudioSharedPcm,"one physical shared owner");if(fail){e="Rejected fixture backend";return false;}h=next++;feeds[h]=f;return true;}
 void stop(uint64_t h)override{feeds.erase(h);pauses.erase(h);}
 void pause(uint64_t h,bool p)override{pauses[h]=p;}
 bool active(uint64_t h)const override{auto i=feeds.find(h);return i!=feeds.end()&&!i->second->ended();}
};
